import json
from pathlib import Path

from developer_agent import run_developer


# Read the plan generated by the Planner Agent
with open(
    "artifacts/plan.json",
    "r",
    encoding="utf-8"
) as file:
    plan = json.load(file)


# Run the Developer Agent
code = run_developer(plan)


# Create the generated folder if it does not exist
Path("generated").mkdir(exist_ok=True)


# Save the generated navigation logic
Path("generated/navigation_logic.py").write_text(
    code,
    encoding="utf-8"
)


# Display the generated navigation logic after the test
print("Generated navigation logic:")
print()
print(code)